// Verify Linear webhook signature — fail-closed if signature missing or wrong.
// Linear posts the HMAC-SHA256 of the raw body in the 'linear-signature' header.
const crypto = require('crypto');
const sig = $input.first().headers['linear-signature'];
const secret = $node['SET_DEFAULTS'].json['linear_webhook_secret'];
const rawBody = JSON.stringify($input.first().body);

if (!sig || !secret || secret.startsWith('<')) {
  return [{ json: { ok: false, error: 'missing_signature_or_secret' } }];
}

const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
if (expected !== sig) {
  return [{ json: { ok: false, error: 'signature_mismatch' } }];
}

const event = $input.first().body;
if (event.type !== 'Issue' || event.action !== 'update') {
  return [{ json: { ok: false, error: 'unsupported_event', type: event.type, action: event.action } }];
}

return [{ json: { ok: true, issue: event.data, change: event.updatedFrom || {} } }];
